阅读下面的程序，输出结果是什么？
```c
#include <stdio.h>
#include <stddef.h>

int sum_array(const int *values, size_t count) {
    int total = 0;
    for (size_t i = 0; i < count; ++i) {
        total += values[i];
    }
    return total;
}

int main(void) {
    int values[] = {1, 3, 5, 7};
    size_t count = sizeof(values) / sizeof(values[0]);
    printf("%d\n", sum_array(values, count));
    return 0;
}
```
